// Lingua Tungga runtime, inlined into every generated package.
// Regenerated by `lt build`; do not edit by hand.

export type Unit = null;

export interface Displayable {
  readonly __lt_display: (value: any) => string;
}

export type Opt<T> =
  | { readonly tag: "some"; readonly values: readonly [T]; readonly __lt_display: (value: any) => string; readonly __lt_order: number }
  | { readonly tag: "none"; readonly values: readonly []; readonly __lt_display: (value: any) => string; readonly __lt_order: number };

export type Res<T, E> =
  | { readonly tag: "ok"; readonly values: readonly [T]; readonly __lt_display: (value: any) => string; readonly __lt_order: number }
  | { readonly tag: "err"; readonly values: readonly [E]; readonly __lt_display: (value: any) => string; readonly __lt_order: number };

export function disp(value: unknown): string {
  if (typeof value === "bigint") return value.toString();
  if (typeof value === "string") return value;
  if (typeof value === "number") {
    return Number.isInteger(value) ? value.toFixed(1) : String(value);
  }
  if (typeof value === "boolean") return value ? "true" : "false";
  if (value === null || value === undefined) return "None";
  const object = value as any;
  if (typeof object.__lt_display === "function") return object.__lt_display(value);
  if (typeof object.__lt_to_string === "function") return object.__lt_to_string();
  if (typeof object.toString === "function" && object.toString !== Object.prototype.toString) {
    return object.toString();
  }
  return JSON.stringify(value);
}

export function eq(a: unknown, b: unknown): boolean {
  if (a === b) return true;
  const left = a as any;
  const right = b as any;
  if (left === null || right === null || left === undefined || right === undefined) return false;
  if (typeof left === "bigint" || typeof right === "bigint") return left === right;
  if (typeof left !== "object" || typeof right !== "object") return left === right;
  if (typeof left.__lt_eq === "function") return left.__lt_eq(right);
  if (Array.isArray(left) && Array.isArray(right)) {
    if (left.length !== right.length) return false;
    return left.every((item: unknown, index: number) => eq(item, right[index]));
  }
  if ("tag" in left && "tag" in right) {
    return left.tag === right.tag && eq(left.values, right.values);
  }
  return false;
}

export function cmp(a: unknown, b: unknown): number {
  const leftValue = a as any;
  if (leftValue !== null && typeof leftValue === "object") {
    if (typeof leftValue.__lt_cmp === "function") return leftValue.__lt_cmp(b);
    const rightValue = b as any;
    if (
      typeof leftValue.__lt_order === "number" &&
      rightValue !== null &&
      typeof rightValue === "object" &&
      typeof rightValue.__lt_order === "number"
    ) {
      if (leftValue.__lt_order !== rightValue.__lt_order) {
        return leftValue.__lt_order < rightValue.__lt_order ? -1 : 1;
      }
      const leftItems = leftValue.values ?? [];
      const rightItems = rightValue.values ?? [];
      for (let index = 0; index < Math.min(leftItems.length, rightItems.length); index += 1) {
        const step = cmp(leftItems[index], rightItems[index]);
        if (step !== 0) return step;
      }
      return leftItems.length - rightItems.length;
    }
  }
  if (typeof a === "bigint" && typeof b === "bigint") return a < b ? -1 : a > b ? 1 : 0;
  if (typeof a === "number" && typeof b === "number") return a < b ? -1 : a > b ? 1 : 0;
  if (typeof a === "string" && typeof b === "string") return a < b ? -1 : a > b ? 1 : 0;
  if (typeof a === "boolean" && typeof b === "boolean") return Number(a) - Number(b);
  const left = disp(a);
  const right = disp(b);
  return left < right ? -1 : left > right ? 1 : 0;
}

// --- Int: i64 with wrapping overflow ---------------------------------------
export const iadd = (a: bigint, b: bigint): bigint => BigInt.asIntN(64, a + b);
export const isub = (a: bigint, b: bigint): bigint => BigInt.asIntN(64, a - b);
export const imul = (a: bigint, b: bigint): bigint => BigInt.asIntN(64, a * b);
export const idiv = (a: bigint, b: bigint): bigint => BigInt.asIntN(64, a / b);
export const irem = (a: bigint, b: bigint): bigint => BigInt.asIntN(64, a % b);
export const ineg = (a: bigint): bigint => BigInt.asIntN(64, -a);

// --- Option ----------------------------------------------------------------
const noneValue: Opt<never> = {
  tag: "none",
  values: [],
  __lt_order: 0,
  __lt_display: (value: any) => (value.tag === "none" ? "None" : `Some(${disp(value.values[0])})`),
};

export function Some<T>(value: T): Opt<T> {
  return { tag: "some", values: [value], __lt_order: 1, __lt_display: noneValue.__lt_display };
}

export function None<T>(): Opt<T> {
  return noneValue as Opt<T>;
}

export const optIsSome = <T>(value: Opt<T>): boolean => value.tag === "some";
export const optIsNone = <T>(value: Opt<T>): boolean => value.tag === "none";

export function optUnwrap<T>(value: Opt<T>): T {
  if (value.tag === "none") throw new Error("unwrap on None");
  return value.values[0];
}

export function optUnwrapOr<T>(value: Opt<T>, fallback: T): T {
  return value.tag === "some" ? value.values[0] : fallback;
}

export function optMap<T, U>(value: Opt<T>, f: (value: T) => U): Opt<U> {
  return value.tag === "some" ? Some(f(value.values[0])) : None<U>();
}

export function optAndThen<T, U>(value: Opt<T>, f: (value: T) => Opt<U>): Opt<U> {
  return value.tag === "some" ? f(value.values[0]) : None<U>();
}

// --- Result ----------------------------------------------------------------
const resDisplay = (value: any): string =>
  value.tag === "ok" ? `Ok(${disp(value.values[0])})` : `Err(${disp(value.values[0])})`;

export function Ok<T, E>(value: T): Res<T, E> {
  return { tag: "ok", values: [value], __lt_order: 0, __lt_display: resDisplay };
}

export function Err<T, E>(value: E): Res<T, E> {
  return { tag: "err", values: [value], __lt_order: 1, __lt_display: resDisplay };
}

export const resIsOk = <T, E>(value: Res<T, E>): boolean => value.tag === "ok";
export const resIsErr = <T, E>(value: Res<T, E>): boolean => value.tag === "err";

export function resUnwrap<T, E>(value: Res<T, E>): T {
  if (value.tag === "err") throw new Error(`unwrap on Err(${disp(value.values[0])})`);
  return value.values[0];
}

export function resUnwrapOr<T, E>(value: Res<T, E>, fallback: T): T {
  return value.tag === "ok" ? value.values[0] : fallback;
}

export function resMap<T, U, E>(value: Res<T, E>, f: (value: T) => U): Res<U, E> {
  return value.tag === "ok" ? Ok<U, E>(f(value.values[0])) : Err<U, E>(value.values[0]);
}

export function resMapErr<T, E, F>(value: Res<T, E>, f: (value: E) => F): Res<T, F> {
  return value.tag === "ok" ? Ok<T, F>(value.values[0]) : Err<T, F>(f(value.values[0]));
}

export function resAndThen<T, U, E>(value: Res<T, E>, f: (value: T) => Res<U, E>): Res<U, E> {
  return value.tag === "ok" ? f(value.values[0]) : Err<U, E>(value.values[0]);
}

// --- Str helpers (indexing is by Unicode code point) -----------------------
export const strLen = (value: string): bigint => BigInt([...value].length);

export function strSlice(value: string, start: bigint, end: bigint): string {
  return [...value].slice(Number(start), Number(end)).join("");
}

export const strChars = (value: string): LList<string> => new LList([...value]);

export function strTrimIndent(value: string): string {
  const lines = value.replace(/^\n/, "").replace(/\n[ \t]*$/, "").split("\n");
  const indents = lines
    .filter((line) => line.trim().length > 0)
    .map((line) => line.match(/^[ \t]*/)?.[0].length ?? 0);
  const common = indents.length === 0 ? 0 : Math.min(...indents);
  return lines.map((line) => line.slice(common)).join("\n");
}

export function strParseInt(value: string): Opt<bigint> {
  const trimmed = value.trim();
  if (!/^[+-]?\d+$/.test(trimmed)) return None<bigint>();
  try {
    return Some(BigInt(trimmed));
  } catch {
    return None<bigint>();
  }
}

export function strParseFloat(value: string): Opt<number> {
  const trimmed = value.trim();
  if (trimmed === "") return None<number>();
  const parsed = Number(trimmed);
  return Number.isNaN(parsed) ? None<number>() : Some(parsed);
}

export const strSplit = (value: string, separator: string): LList<string> =>
  new LList(value.split(separator));

export const strReplace = (value: string, from: string, to: string): string =>
  from === "" ? value : value.split(from).join(to);

// --- Immutable collections -------------------------------------------------
export class LList<T> {
  readonly items: readonly T[];

  constructor(items: readonly T[]) {
    this.items = items;
  }

  len(): bigint {
    return BigInt(this.items.length);
  }

  get(index: bigint): Opt<T> {
    const position = Number(index);
    if (position < 0 || position >= this.items.length) return None<T>();
    return Some(this.items[position]);
  }

  push(value: T): LList<T> {
    return new LList([...this.items, value]);
  }

  pop(): Opt<T> {
    return this.items.length === 0 ? None<T>() : Some(this.items[this.items.length - 1]);
  }

  map<U>(f: (value: T) => U): LList<U> {
    return new LList(this.items.map(f));
  }

  filter(f: (value: T) => boolean): LList<T> {
    return new LList(this.items.filter(f));
  }

  fold<A>(init: A, f: (accumulator: A, value: T) => A): A {
    let result = init;
    for (const item of this.items) result = f(result, item);
    return result;
  }

  any(f: (value: T) => boolean): boolean {
    return this.items.some(f);
  }

  all(f: (value: T) => boolean): boolean {
    return this.items.every(f);
  }

  sort(): LList<T> {
    return new LList([...this.items].sort(cmp));
  }

  reverse(): LList<T> {
    return new LList([...this.items].reverse());
  }

  concat(other: LList<T>): LList<T> {
    return new LList([...this.items, ...other.items]);
  }

  contains(value: T): boolean {
    return this.items.some((item) => eq(item, value));
  }

  index_of(value: T): Opt<bigint> {
    const index = this.items.findIndex((item) => eq(item, value));
    return index < 0 ? None<bigint>() : Some(BigInt(index));
  }

  join(separator: string): string {
    return this.items.map(disp).join(separator);
  }

  __lt_eq(other: unknown): boolean {
    return other instanceof LList && eq(this.items, other.items);
  }

  __lt_to_string(): string {
    return `List(${this.items.map(disp).join(", ")})`;
  }
}

export class LSet<T> {
  readonly items: readonly T[];

  constructor(items: readonly T[]) {
    const unique: T[] = [];
    for (const item of items) {
      if (!unique.some((existing) => eq(existing, item))) unique.push(item);
    }
    this.items = unique.sort(cmp);
  }

  len(): bigint {
    return BigInt(this.items.length);
  }

  insert(value: T): LSet<T> {
    return new LSet([...this.items, value]);
  }

  remove(value: T): LSet<T> {
    return new LSet(this.items.filter((item) => !eq(item, value)));
  }

  contains(value: T): boolean {
    return this.items.some((item) => eq(item, value));
  }

  union(other: LSet<T>): LSet<T> {
    return new LSet([...this.items, ...other.items]);
  }

  intersect(other: LSet<T>): LSet<T> {
    return new LSet(this.items.filter((item) => other.contains(item)));
  }

  difference(other: LSet<T>): LSet<T> {
    return new LSet(this.items.filter((item) => !other.contains(item)));
  }

  __lt_eq(other: unknown): boolean {
    return other instanceof LSet && eq(this.items, other.items);
  }

  __lt_to_string(): string {
    return `Set(${this.items.map(disp).join(", ")})`;
  }
}

export class LMap<K, V> {
  readonly entries: readonly (readonly [K, V])[];

  constructor(entries: readonly (readonly [K, V])[]) {
    const sorted = [...entries].sort((left, right) => cmp(left[0], right[0]));
    const unique: (readonly [K, V])[] = [];
    for (const entry of sorted) {
      const existing = unique.findIndex((candidate) => eq(candidate[0], entry[0]));
      if (existing >= 0) unique[existing] = entry;
      else unique.push(entry);
    }
    this.entries = unique;
  }

  static empty<K, V>(): LMap<K, V> {
    return new LMap<K, V>([]);
  }

  len(): bigint {
    return BigInt(this.entries.length);
  }

  get(key: K): Opt<V> {
    const entry = this.entries.find((candidate) => eq(candidate[0], key));
    return entry === undefined ? None<V>() : Some(entry[1]);
  }

  insert(key: K, value: V): LMap<K, V> {
    return new LMap([...this.entries, [key, value] as const]);
  }

  remove(key: K): LMap<K, V> {
    return new LMap(this.entries.filter((entry) => !eq(entry[0], key)));
  }

  keys(): LList<K> {
    return new LList(this.entries.map((entry) => entry[0]));
  }

  values(): LList<V> {
    return new LList(this.entries.map((entry) => entry[1]));
  }

  contains_key(key: K): boolean {
    return this.entries.some((entry) => eq(entry[0], key));
  }

  __lt_eq(other: unknown): boolean {
    return other instanceof LMap && eq(this.entries, other.entries);
  }

  __lt_to_string(): string {
    return `Map(${this.entries.map((entry) => `${disp(entry[0])}: ${disp(entry[1])}`).join(", ")})`;
  }
}

// --- Test assertions -------------------------------------------------------
export function expectEqual(actual: unknown, expected: unknown): void {
  if (!eq(actual, expected)) {
    throw new Error(`assertion failed: expected ${disp(expected)}, got ${disp(actual)}`);
  }
}

export function expectNotEqual(actual: unknown, expected: unknown): void {
  if (eq(actual, expected)) {
    throw new Error(`assertion failed: expected ${disp(actual)} to differ from ${disp(expected)}`);
  }
}

export function expectTrue(value: boolean): void {
  if (!value) throw new Error("assertion failed: expected true");
}

export function expectFalse(value: boolean): void {
  if (value) throw new Error("assertion failed: expected false");
}
